func WithBudget(total time.Duration) func(http.Handler) http.Handler {
    return func(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
            ctx, cancel := context.WithTimeout(r.Context(), total)
            defer cancel() // 不 cancel 会把 timer 留到 total 到期，高 QPS 下是可观的内存与 GC 压力
            next.ServeHTTP(w, r.WithContext(ctx))
        })
    }
}

// 每往下一跳调用前，先扣掉本层自己的开销，再把剩余时间交给下游
// selfCost 取「本层 p99 减去下游 p99」，代表编排与序列化的实测成本
func nextHop(ctx context.Context, selfCost time.Duration) (context.Context, context.CancelFunc, error) {
    dl, ok := ctx.Deadline()
    if !ok {
        // 没预算就不发起调用：一个没有 deadline 的跨进程调用会一直占着连接和 goroutine
        return nil, nil, errors.New("rpc: refuse to call without deadline")
    }
    remain := time.Until(dl) - selfCost
    if remain <= 0 {
        // 剩余时间已经不够，直接放弃比发出一个注定超时的请求便宜
        return nil, nil, context.DeadlineExceeded
    }
    child, cancel := context.WithTimeout(ctx, remain)
    return

