    "time"

    "github.com/redis/go-redis/v9"
)

// 读己之写：写后把「这个用户」的读钉在主库上一小段时间。
// 它只解决「自己看不到自己刚改的内容」，不解决「别人看到旧值」——
// 多数被描述成「必须实时」的需求其实只是前者。
type StickyRouter struct {
    primary *sql.DB
    replica *sql.DB
    rdb     *redis.Client // 标记必须跨实例共享，否则请求换一台机器就失效
    window  time.Duration // 取复制延迟的 p99；用平均值会让尾部请求继续读到旧值
}

func stickyKey(userID int64) string {
    return fmt.Sprintf("sticky:primary:%d", userID)
}

// 写操作成功后立刻调用。靠 TTL 自然失效，不需要任何清理任务。
func (r *StickyRouter) MarkWritten(ctx context.Context, userID int64) error {
    return r.rdb.Set(ctx, stickyKey(userID), "1", r.window).Err()
}

// 读路径取连接。err != nil 时故意返回主库：
// 标记服务不可用时宁可多压主库，也不要静默降级成「可能读到旧值」。
func (r *StickyRouter) Pick(ctx context.Context, userID int64) *sql.DB {
    n, err := r.rdb.Exists(ctx, stickyKey(userID)).Result()
    if err != nil || n > 0 {
        return r.primary
    }
    return r.replica
