import { create, type StateCreator } from 'zustand'

type DraftSlice = {
  title: string
  body: string
  setTitle: (t: string) => void
  setBody: (b: string) => void
}

type FilterSlice = {
  keyword: string
  tags: string[]
  setKeyword: (k: string) => void
  toggleTag: (t: string) => void
}

type Workspace = DraftSlice & FilterSlice

// 切片签名里把完整状态类型带上，这样切片内部也能读到别的切片
const createDraftSlice: StateCreator<Workspace, [], [], DraftSlice> = (set) => ({
  title: '',
  body: '',
  setTitle: (t) => set({ title: t }),
  setBody: (b) => set({ body: b }),
})

const createFilterSlice: StateCreator<Workspace, [], [], FilterSlice> = (set, get) => ({
  keyword: '',
  tags: [],
  setKeyword: (k) => set({ keyword: k }),
  toggleTag: (t) =>
    set((s) => ({
      tags: s.tags.includes(t) ? s.tags.filter((x) => x !== t) : [...s.tags, t],
    })),
})

export const useWorkspace = create<Workspace>()((...a) => ({
  ...createDraftSlice(...a),
  ...createFilterSlice(...a),
})) 组织方式 适合 优点 代价 单个大 store 状态字段少于十几个的小应用 没有跨 store 协调问题 领域边界消失，改任何东西都要通读全文件 按领域多 store 中型以上应用，默认选择 边界清晰，可独立测试与持久化 跨领域流程需要外部函数来编排 单 store 加切片组合 领域间联系紧密但文件太长 文件可拆，共享状态仍然容易 切片之间容易互相依赖，边界名存实亡 每个组件一个 store 复杂表单或编辑器实例 实例隔离，卸载即回收 需要工厂函数与提供者，样板略多 按页面拆 store 页面间状态毫无关联 清理时机明确 跨页共享的东西会被迫复制 方法放 store 还是放外部 这段逻辑 放哪 理由 只改一个 store 的状态 store 的方法 数据与操作在一起，调用方不用额外找函数 需要读写多个 store 外部函数 依赖关系显式，避免 store 之间互相导入形成环 多步流程带回滚 外部函数 流程编排不属于任何单一领域 纯计算的派生值 选择器或外部函数 存进状态就要负责在每个更新处同步，漏一处就自相矛盾 格式化与校验 外部纯函数 不依赖状态，便于单独测试 与接口交互并更新状态 store 的方法 结果要落到状态上，放外面会多一次转发 开销大的派生计算 外部记忆化函数 放选择器里每次渲染都算，放状态里又要同步 ✅ 一条简明规则 改状态的放 store，只读不改的放外部；跨 store 的一律放外部。 store 间不互相导入，就没有循环依赖和「改一个 store 引发另一个 store 连锁更新」这类难追踪问题。 store 里做异步：把状态显式建模 // 异步写操作：加载中与错误

