import "slices"

type Row struct {
	ID   int64
	Name string
}

// 动作一：预分配。容量是第三个参数；写成 make([]Row, n) 再 append，
// 结果是 2n 个元素且前 n 个全是零值——这是每个人都会犯一次的错。
func collect(ids []int64) []Row {
	out := make([]Row, 0, len(ids)) // 一次分配到位，后续 append 不再扩容
	for _, id := range ids {
		out = append(out, Row{ID: id})
	}
	return out
}

// 动作二：把一段切片交给外部之前先把容量卡死。
// a[0:n] 的容量默认延伸到底层数组末尾，调用方一次 append 就会
// 就地写进 a 的第 n+1 个位置，而你完全收不到通知。
func head(a []Row, n int) []Row {
	if n > len(a) {
		n = len(a)
	}
	return a[0:n:n] // 三索引：len 与 cap 都是 n，对方 append 必然分配新数组
}

// 动作三：需要独立数据就显式克隆，不要指望调用方不改。
func snapshot(a []Row) []Row { return slices.Clone(a) }

// 动作四：从大缓冲里只留一小段，必须复制。
// raw 可能是几 MB 的读缓冲，返回值只有 n 字节，
// 但回收单位是整块底层数组，不复制就等于把这几 MB 一直占着。
func keepPrefix(raw []byte, n int) []byte {
	out := make([]byte, n)
	copy(out, raw[:n])
	return out
}

