// 定式二：带缓冲 channel 当信号量做限流 —— 不引第三方库时的标准写法
func runLimited(ctx context.Context, jobs []Job, n int) error {
    sem := make(chan struct{}, n)
    var wg sync.WaitGroup
    for _, j := range jobs {
        select {
        case sem <- struct{}{}: // 拿不到令牌就阻塞在这里，这就是天然的背压
        case <-ctx.Done():
            wg.Wait() // 已经起来的任务必须等它们退出，否则就是 goroutine 泄漏
            return ctx.Err()
        }
        wg.Add(1) // Add 必须在 go 语句之前，为什么见原理层
        go func(j Job) {
            defer wg.Done()
            defer func() { <-sem }() // 归还令牌要放在 defer 里，panic 时也得还
            j.Run(ctx)
        }(j)
    }
    wg.Wait()
    return nil
}

