    sort.Slice(users, func(i, j int) bool { return users[i].Age < users[j].Age })
    slices.SortFunc(users, func(a, b User) int { return cmp.Compare(a.Age, b.Age) })

    // 2) 判断包含：新写法是线性扫描，高频查询仍应改用 map
    found := false
    for _, v := range xs {
        if v == target {
            found = true
            break
        }
    }
    found = slices.Contains(xs, target)
    _ = found

    // 3) 取最值：切片用 slices，两个标量用 1.21 起的语言内置函数
    mx := xs[0]
    for _, v := range xs[1:] {
        if v > mx {
            mx = v
        }
    }
    if len(xs) > 0 { // slices.Max 对空切片直接 panic，不是返回零值
