func (s *Stack[T]) Push(v T) { s.items = append(s.items, v) }

// 返回 (T, bool) 而不是单个 T：让「空栈」和「栈顶恰好是零值」可以区分开
func (s *Stack[T]) Pop() (T, bool) {
    var zero T
    if len(s.items) == 0 {
        return zero, false
    }
    v := s.items[len(s.items)-1]
    s.items[len(s.items)-1] = zero // 置零让被弹出的元素可回收，元素是指针时这行很关键
    s.items = s.items[:len(s.items)-1]
    return v, true
}

