const { monitorEventLoopDelay } = require('node:perf_hooks');

// resolution 是采样间隔，小于它的抖动测不出来；10ms 足够判断「有没有长阻塞」
const h = monitorEventLoopDelay({ resolution: 10 });
h.enable();

const timer = setInterval(() => {
  const p50 = (h.percentile(50) / 1e6).toFixed(1);   // 直方图单位是纳秒
  const p99 = (h.percentile(99) / 1e6).toFixed(1);
  const max = (h.max / 1e6).toFixed(1);
  // 写 stderr 而不是 stdout：不和业务日志混在一起，采集器不会解析失败
  process.stderr.write('lag p50=' + p50 + 'ms p99=' + p99 + 'ms max=' + max + 'ms\n');
  h.reset();   // 必须 reset，否则分位值会被历史尖峰钉死，看不出当前状态
}, 1000);

timer.unref();   // 探针本身不能变成「让进程退不出去」的活跃句柄 然后按下面六步走。每一步都在回答一个具体问题，不要跳步： # 1) 挂探针启动。-r 在业务入口之前加载，启动阶段的阻塞也能测到
node -r /tmp/lag-probe.js server.js

# 2) 加压。空载时事件循环延迟永远接近 0，没有压力的测量没有意义
#    并发要压过服务的处理能力，先从 100 并发起
npx autocannon -c 100 -d 30 http://127.0.0.1:8080/api/orders

# 3) 按线程看 CPU：只有一个线程接近 100%、其余空闲，就是主线程在算东西
top -H -p $(pgrep -f 'node server.js')

# 4) 抓同步 IO。启动完成之后仍然打出 WARNING 的才是问题，启动期读配置属于正常
