async function createOrder(input) {          // input 已经是校验过的普通对象
  const order = await repo.insert(input)     // 不接触 req / res / ctx / reply
  return { id: order.id, status: order.status, createdAt: order.createdAt }
}

// 边界层之一：Express。校验、状态码、序列化都在这一层做完
