  schema: {
    body: createOrderJsonSchema,
    // 注意：response schema 里没声明的字段会被静默丢掉，新增返回字段必须同步改这里
    response: { 201: orderJsonSchema },
  },
}, async (req, reply) => {
  reply.code(201)
  return createOrder(req.body)               // 返回普通对象，不要自己 JSON.stringify
})

